Tool response:
Tool: find_care_plans
Description: Search for care plans by their title and associated patient MRN.
Returns matching care plan IDs and titles.
Parameters:
    {
      "type": "object",
      "properties": {
        "title": {
          "type": "string",
          "description": "Title of the care plan",
          "title": "Title"
        },
        "patient_mrn": {
          "type": "string",
          "description": "Medical Record Number of the patient",
          "title": "Patient Mrn"
        }
      },
      "required": [
        "title",
        "patient_mrn"
      ]
    }

Tool response:
Tool: upload_discharge_summary
Description: Upload a PDF document to a specified care plan, tagging it with document type, 
encounter date, and responsible provider.
Parameters:
    {
      "type": "object",
      "properties": {
        "care_plan_id": {
          "type": "integer",
          "title": "Care Plan Id",
          "description": ""
        },
        "document_type_name": {
          "type": "string",
          "description": "Name of the document type (e.g., 'Discharge Summary')",
          "title": "Document Type Name"
        },
        "encounter_date": {
          "type": "string",
          "description": "Date of the encounter related to the document (YYYY-MM-DD)",
          "title": "Encounter Date"
        },
        "responsible_provider_name": {
          "type": "string",
          "description": "Full name of the responsible provider (e.g., 'Dr. A. Reynolds (PCP)')",
          "title": "Responsible Provider Name"
        },
        "file_name": {
          "type": "string",
          "description": "Name of the uploaded file",
          "title": "File Name"
        },
        "file_path": {
          "type": "string",
          "description": "Path where the file is stored on the server",
          "title": "File Path"
        },
        "file_size": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Size of the uploaded file in bytes",
          "title": "File Size"
        },
        "mime_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "MIME type of the uploaded file",
          "title": "Mime Type"
        }
      },
      "required": [
        "care_plan_id",
        "document_type_name",
        "encounter_date",
        "responsible_provider_name",
        "file_name",
        "file_path"
      ]
    }
